import test from 'node:test';
import assert from 'node:assert/strict';
import { exportCsv } from '../src/export.js';
import { createInvoice, issueInvoice, invoiceTotals } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('exportCsv returns header for empty array', () => {
  const csv = exportCsv([]);
  assert.equal(csv, 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due\n');
});

test('exportCsv returns header line', () => {
  const csv = exportCsv([]);
  const lines = csv.split('\n');
  assert.equal(lines[0], 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due');
});

test('exportCsv exports single issued invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const issued = issueInvoice(r.value, []);
  const csv = exportCsv([issued.value]);
  const lines = csv.split('\n');
  assert.equal(lines.length, 3);
  assert.match(lines[1], /^INV-2026-0001,Northwind Studio,2026-10-07,2026-11-06,issued/);
});

test('exportCsv includes customer name', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(r.value, []);
  const csv = exportCsv([issued.value]);
  assert.match(csv, /Kite & Co/);
});

test('exportCsv formats amounts as plain euros with 2 decimals', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(r.value, []);
  const csv = exportCsv([issued.value]);
  assert.match(csv, /\d+\.\d{2}/);
});

test('exportCsv does not include currency symbol', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(r.value, []);
  const csv = exportCsv([issued.value]);
  assert.doesNotMatch(csv, /€/);
});

test('exportCsv does not use thousands separator', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });
  const issued = issueInvoice(r.value, []);
  const csv = exportCsv([issued.value]);
  assert.doesNotMatch(csv, /,\d{3}/);
  assert.match(csv, /120000\./);
});

test('exportCsv uses dot as decimal separator', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(r.value, []);
  const csv = exportCsv([issued.value]);
  const lines = csv.split('\n');
  const fields = lines[1].split(',');
  for (let i = 5; i <= 9; i++) {
    assert.match(fields[i], /^\d+\.\d{2}$/);
  }
});

test('exportCsv quotes fields with commas', () => {
  const r = createInvoice({
    customerId: 'C-006',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(r.value, []);
  const csv = exportCsv([issued.value]);
  assert.match(csv, /"Marlow "The Print Shop""/);
});

test('exportCsv doubles double quotes in fields', () => {
  const r = createInvoice({
    customerId: 'C-006',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(r.value, []);
  const csv = exportCsv([issued.value]);
  assert.match(csv, /"Marlow ""The Print Shop"""/);
});

test('exportCsv exports multiple invoices in order', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const r2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const issued1 = issueInvoice(r1.value, []);
  const issued2 = issueInvoice(r2.value, ['INV-2026-0001']);
  const csv = exportCsv([issued1.value, issued2.value]);
  const lines = csv.split('\n');
  assert.equal(lines.length, 4);
  assert.match(lines[1], /INV-2026-0001/);
  assert.match(lines[2], /INV-2026-0002/);
});

test('exportCsv includes invoice number', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(r.value, []);
  const csv = exportCsv([issued.value]);
  assert.match(csv, /INV-2026-0001/);
});

test('exportCsv includes issue date', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(r.value, []);
  const csv = exportCsv([issued.value]);
  assert.match(csv, /2026-10-07/);
});

test('exportCsv includes due date', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(r.value, []);
  const csv = exportCsv([issued.value]);
  assert.match(csv, /2026-11-06/);
});

test('exportCsv includes status', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(r.value, []);
  const csv = exportCsv([issued.value]);
  assert.match(csv, /,issued/);
});

test('exportCsv includes subtotal', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const issued = issueInvoice(r.value, []);
  const totals = invoiceTotals(issued.value);
  const csv = exportCsv([issued.value]);
  const expectedSubtotal = (totals.subtotal / 100).toFixed(2);
  assert.match(csv, new RegExp(expectedSubtotal.replace('.', '\\.')));
});

test('exportCsv includes discount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const issued = issueInvoice(r.value, []);
  const csv = exportCsv([issued.value]);
  assert.match(csv, /\d+\.\d{2},\d+\.\d{2}/);
});

test('exportCsv includes VAT', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const issued = issueInvoice(r.value, []);
  const csv = exportCsv([issued.value]);
  const lines = csv.split('\n');
  const fields = lines[1].split(',');
  assert.match(fields[7], /^\d+\.\d{2}$/);
});

test('exportCsv includes total', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const issued = issueInvoice(r.value, []);
  const totals = invoiceTotals(issued.value);
  const csv = exportCsv([issued.value]);
  const expectedTotal = (totals.total / 100).toFixed(2);
  assert.match(csv, new RegExp(expectedTotal.replace('.', '\\.')));
});

test('exportCsv includes due amount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const issued = issueInvoice(r.value, []);
  const totals = invoiceTotals(issued.value);
  const csv = exportCsv([issued.value]);
  const expectedDue = (totals.total / 100).toFixed(2);
  const lines = csv.split('\n');
  const fields = lines[1].split(',');
  assert.match(fields[9], new RegExp(`^${expectedDue.replace('.', '\\.')}$`));
});

test('exportCsv with partial payment shows reduced due', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const issued = issueInvoice(r.value, []);
  const totals = invoiceTotals(issued.value);
  const withPayment = recordPayment(issued.value, { amount: 5000, date: '2026-10-08' });
  const csv = exportCsv([withPayment.value]);
  const expectedDue = ((totals.total - 5000) / 100).toFixed(2);
  const lines = csv.split('\n');
  const fields = lines[1].split(',');
  assert.match(fields[9], new RegExp(`^${expectedDue.replace('.', '\\.')}$`));
});

test('exportCsv ends with newline', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(r.value, []);
  const csv = exportCsv([issued.value]);
  assert.equal(csv[csv.length - 1], '\n');
});

test('exportCsv lines end with newline', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(r.value, []);
  const csv = exportCsv([issued.value]);
  const lines = csv.split('\n');
  for (let i = 0; i < lines.length - 1; i++) {
    assert.notEqual(lines[i], '');
  }
});

test('exportCsv with draft invoice has empty number', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const csv = exportCsv([r.value]);
  const lines = csv.split('\n');
  const fields = lines[1].split(',');
  assert.equal(fields[0], '');
});

test('exportCsv preserves invoice order', () => {
  const invoices = [];
  for (let i = 1; i <= 3; i++) {
    const r = createInvoice({
      customerId: 'C-001',
      issueDate: `2026-10-0${i}`,
      lines: [{ sku: 'DES-HOUR', qty: i }],
    });
    const issued = issueInvoice(r.value, invoices.map(inv => inv.number));
    invoices.push(issued.value);
  }
  const csv = exportCsv(invoices);
  const lines = csv.split('\n');
  for (let i = 0; i < 3; i++) {
    assert.match(lines[i + 1], new RegExp(`INV-2026-000${i + 1}`));
  }
});

test('exportCsv with multiple VAT rates', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'PRINT-A4', qty: 100 },
    ],
  });
  const issued = issueInvoice(r.value, []);
  const csv = exportCsv([issued.value]);
  const lines = csv.split('\n');
  assert.equal(lines.length, 3);
});

test('exportCsv with discount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 10 }],
  });
  const issued = issueInvoice(r.value, []);
  const totals = invoiceTotals(issued.value);
  const csv = exportCsv([issued.value]);
  const expectedDiscount = (totals.discount / 100).toFixed(2);
  assert.match(csv, new RegExp(expectedDiscount.replace('.', '\\.')));
});

test('exportCsv with VAT exempt product', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }],
  });
  const issued = issueInvoice(r.value, []);
  const csv = exportCsv([issued.value]);
  const lines = csv.split('\n');
  const fields = lines[1].split(',');
  assert.match(fields[7], /^0\.00$/);
});

test('exportCsv csv is valid format', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const issued = issueInvoice(r.value, []);
  const csv = exportCsv([issued.value]);
  const lines = csv.split('\n');
  const headerFields = lines[0].split(',');
  const dataFields = lines[1].split(',');
  assert.equal(headerFields.length, 10);
  assert.equal(dataFields.length, 10);
});

test('exportCsv amounts have 2 decimal places', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 1 }],
  });
  const issued = issueInvoice(r.value, []);
  const csv = exportCsv([issued.value]);
  const lines = csv.split('\n');
  const fields = lines[1].split(',');
  for (let i = 5; i <= 9; i++) {
    assert.match(fields[i], /^\d+\.\d{2}$/);
  }
});

test('exportCsv handles special characters in customer name', () => {
  const r = createInvoice({
    customerId: 'C-006',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(r.value, []);
  const csv = exportCsv([issued.value]);
  assert.match(csv, /"Marlow/);
});

test('exportCsv large invoice list', () => {
  const invoices = [];
  for (let i = 1; i <= 10; i++) {
    const r = createInvoice({
      customerId: 'C-001',
      issueDate: `2026-10-0${String(i).padStart(2, '0')}`,
      lines: [{ sku: 'DES-HOUR', qty: i }],
    });
    const issued = issueInvoice(r.value, invoices.map(inv => inv.number));
    invoices.push(issued.value);
  }
  const csv = exportCsv(invoices);
  const lines = csv.split('\n').filter(l => l);
  assert.equal(lines.length, 11);
});

test('exportCsv with fully paid invoice shows 0 due', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const issued = issueInvoice(r.value, []);
  const totals = invoiceTotals(issued.value);
  const paid = recordPayment(issued.value, { amount: totals.total, date: '2026-10-08' });
  const csv = exportCsv([paid.value]);
  const lines = csv.split('\n');
  const fields = lines[1].split(',');
  assert.match(fields[9], /^0\.00$/);
});

test('exportCsv with zero subtotal (100% discount)', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 100 }],
  });
  const issued = issueInvoice(r.value, []);
  const csv = exportCsv([issued.value]);
  const lines = csv.split('\n');
  const fields = lines[1].split(',');
  assert.match(fields[5], /^\d+\.\d{2}$/);
});

